tmnxResvCbsPoolThreshGreen = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 2, 2, 0, 49)).setObjects(("TIMETRA-PORT-MIB", "tmnxObjType"), ("TIMETRA-PORT-MIB", "tmnxObjPortId"), ("TIMETRA-PORT-MIB", "tmnxObjMdaId"), ("TIMETRA-PORT-MIB", "tmnxObjAppType"), ("TIMETRA-PORT-MIB", "tmnxObjAppPool"), ("TIMETRA-PORT-MIB", "tmnxObjAppResvSize"), ("TIMETRA-PORT-MIB", "tmnxObjAppSumOfQResvSize"), ("TIMETRA-PORT-MIB", "tmnxObjAppResvCbsOld"), ("TIMETRA-PORT-MIB", "tmnxObjAppResvCbsNew"), ("TIMETRA-PORT-MIB", "tmnxObjAppResvSizeOld"))
