tmnxCohOptPortDispCtrlMode = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 2, 4, 71, 1, 3), TmnxOpticalDispCtrlMode().clone('automatic')).setMaxAccess("readwrite")
