tmnxPortEtherSymMonSfThreshold = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 2, 4, 82, 1, 4), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 9)).clone(0)).setMaxAccess("readwrite")
